import type { D1AuthoredBank } from '../corpus'

export const LEMBAH_AWAN_D_R8: D1AuthoredBank = {
  universeId: 'lembah-awan',
  rubricId: 'D-R8',
  STRONG: [
    { chapters: [
      { chapterNumber: 41, title: 'Bambu Melenting di Lereng', paragraphs: ['Karsa menemukan tiga bilah bambu penahan tanah melenting menjauhi lereng setelah kru Bagas menancapkan tiang berat di atas kebun kopi. Retakan tipis membelah jalan menuju sekolah. Vina memasang bilah tambahan pada jarak satu depa, lalu meminta Bu Ningsih memindahkan murid dari ruang paling dekat tebing sebelum kantor menyebut retakan itu biasa.'] },
      { chapterNumber: 42, title: 'Kelereng Bergerak Sendiri', paragraphs: ['Bu Ningsih meletakkan kelereng murid pada lantai kelas dan semuanya menggelinding ke dinding lereng. Vina mengukur pergeseran bilah dengan benang, sementara para orang tua memindahkan buku ke balai. Sekolah belum runtuh, namun lantai miring dan bambu membuktikan tanah terus bergerak. Mereka harus memilih tempat aman sebelum hujan berikutnya tiba.'] },
      { chapterNumber: 43, title: 'Cekungan di Kebun Vina', paragraphs: ['Mbah Ripto menunjukkan cekungan kosong di bawah teras Vina yang dapat menerima lumpur bila jalurnya dibuka. Jalur terpendek melewati tungku pengering kopi warisan ayahnya. Bu Ningsih menolak meminta pengorbanan itu dan mengusulkan evakuasi panjang. Vina menandai arah aliran dengan sekam, tetapi belum sanggup menjawab apa yang rela ia hilangkan.'] },
      { chapterNumber: 44, title: 'Latihan Turun Tanpa Panik', paragraphs: ['Anak-anak berlatih meninggalkan kelas melalui kebun pisang, dipandu tali yang dipasang Karsa. Dua murid kecil tersandung saat orang dewasa berteriak, sehingga Bu Ningsih mengulang latihan dalam diam memakai ketukan kaleng. Vina menyiapkan cangkul dekat tungku. Persiapan itu menyelamatkan waktu, tetapi tidak menghentikan massa tanah yang semakin menekan bilah bambu.'] },
      { chapterNumber: 45, title: 'Bagas Menarik Pekerjanya', paragraphs: ['Bagas menarik semua pekerja dari lereng dan melarang kayu kantor dipakai menyangga sekolah. Ia menawarkan truk untuk memindahkan keluarga Vina bila mereka menyerahkan cekungan kepada kebun teh. Vina menolak tawaran itu. Bu Ningsih marah karena penolakannya mempertaruhkan murid, lalu keduanya berpisah tanpa sepakat apakah sekolah atau rumah harus dikorbankan.'] },
      { chapterNumber: 46, title: 'Hujan Mematahkan Dua Bilah', paragraphs: ['Hujan malam mematahkan dua bilah dan mendorong tanah sampai pagar sekolah. Bu Ningsih menutup kelas sepenuhnya, sedangkan warga menggali parit pemecah lumpur menuju cekungan. Ujung parit berhenti di dinding teras Vina. Danu menawarkan membongkar tungku sendiri, tetapi Vina meminta semua orang menunggu sampai murid serta keluarga bawah selesai dievakuasi.'] },
      { chapterNumber: 47, title: 'Tungku Warisan Dirobohkan', paragraphs: ['Ketika derak terdengar dari punggung lereng, Vina mengayunkan palu ke tungku pengering keluarganya. Danu dan Karsa merobohkan bata lain, lalu membuka dinding teras selebar dua depa. Lumpur pertama menerobos bekas tungku menuju cekungan. Bu Ningsih membawa murid terakhir turun sambil melihat kebun kopi Vina terbelah oleh aliran cokelat.'] },
      { chapterNumber: 48, title: 'Sekolah Berdiri Tanpa Halaman', paragraphs: ['Longsor berhenti di cekungan setelah meratakan tungku, petak kopi, dan separuh halaman sekolah. Ruang kelas masih berdiri, tetapi Vina kehilangan tempat mengeringkan panen serta pohon terbaik keluarganya. Bu Ningsih meminta maaf karena sempat menjadikan pilihan itu beban Vina seorang. Mereka sepakat sekolah baru tidak boleh dibangun kembali tepat di kaki lereng.'] },
      { chapterNumber: 49, title: 'Kelas Dibuka di Balai', paragraphs: ['Pelajaran dimulai di balai dengan meja tidak seragam dan dinding tanpa jendela. Anak-anak menggambar posisi bilah bambu, bukan untuk memuji bencana, melainkan memahami mengapa tanah bergerak. Vina menjual sisa kopi basah dengan harga rendah. Bu Ningsih menyisihkan sudut kelas untuk rencana tungku bersama yang kelak dapat dipakai semua penanam.'] },
      { chapterNumber: 50, title: 'Lingkar Bata Menampung Hujan', paragraphs: ['Kecamatan melarang pemasangan tiang baru dan menetapkan cekungan sebagai ruang penahan longsor. Sekolah tetap belajar di balai sampai bangunan aman tersedia. Vina menanam kopi pada petak sempit bersama Danu, tanpa janji panen cepat. Di bekas tungku ayah mereka, lingkar bata yang tersisa menampung air hujan sementara bilah bambu baru berdiri lurus di lereng.'] },
    ], justification: 'The ending makes measured slope movement force Vina to destroy her inherited drying kiln and terrace, saving the school while leaving durable economic and spatial loss.' },
    { chapters: [
      { chapterNumber: 41, title: 'Abu Hangat di Daun', paragraphs: ['Abu hangat menempel pada daun teh yang basah meski tidak ada tungku desa menyala. Vina mengikuti serpihannya sampai batas kebun dan menemukan rumput kering sengaja dibiarkan menyambung ke lumbung. Karsa mengenali bekas sabit buatannya pada batang yang dipangkas. Keduanya menduga seseorang menyiapkan jalan api sebelum angin timur menguat.'] },
      { chapterNumber: 42, title: 'Garis Rumput Diputus', paragraphs: ['Vina mengajak keluarga lereng mencabut rumput sepanjang batas rumah, tetapi Karsa menolak memimpin. Ia mengaku pernah menjual enam sabit kepada kru Bagas tanpa menanyakan kegunaannya. Warga mulai meragukannya. Vina meminta Karsa menunjukkan cara membaca arah pangkasan, lalu membiarkan setiap keluarga memeriksa pekarangannya sendiri sebelum memutuskan apakah ia masih layak dipercaya.'] },
      { chapterNumber: 43, title: 'Sekat Pertama Terlalu Sempit', paragraphs: ['Karsa membuat sekat tanah kupas selebar dua langkah di belakang balai. Mereka membakar segenggam ilalang untuk mengujinya, namun bara terbang melewati batas dan menghanguskan pagar kosong. Vina memadamkan api bersama para ibu. Kegagalan itu memaksa Karsa mengakui bahwa angin puncak membutuhkan sekat jauh lebih lebar daripada lahan yang rela diserahkan warga.'] },
      { chapterNumber: 44, title: 'Gentong Berbaris di Punggung', paragraphs: ['Warga menaruh gentong air dan karung tanah di punggung kebun sambil memangkas ranting rendah. Bu Ningsih melatih anak-anak menuju sawah basah bila kentongan berbunyi tiga kali. Bagas menyebut persiapan itu hasutan dan melarang pekerja kebun membantu. Vina tetap membagi kelompok jaga, sedangkan Karsa menandai arah angin dengan pita daun pisang.'] },
      { chapterNumber: 45, title: 'Bengkel Dilempari Jelaga', paragraphs: ['Seseorang melempar jelaga bercampur minyak ke dinding bengkel Karsa pada malam hari. Karsa ingin pergi dari lembah sebelum kebakaran dan berkata semua orang akan menuduhnya bila api muncul. Vina tidak menghapus kesalahannya menjual sabit, tetapi meminta ia memilih apakah pengetahuan tangannya akan dipakai untuk meninggalkan warga atau menyiapkan pertahanan terakhir.'] },
      { chapterNumber: 46, title: 'Angin Membalik Pita Daun', paragraphs: ['Pita daun pisang mendadak mengarah ke rumah-rumah saat angin timur berbelok. Sekat aman kini harus melewati kebun teh Vina yang siap dipetik. Danu menolak karena panen itu membayar kebutuhan mereka sampai musim hujan. Karsa menawarkan membuat bakar-balik lebih dekat lumbung, tetapi percobaan pagar hangus membuktikan jarak tersebut tidak cukup.'] },
      { chapterNumber: 47, title: 'Api Muncul dari Puncak', paragraphs: ['Asap hitam naik dari punggung kebun ketika anak-anak telah turun ke sawah. Kelompok jaga memukul kentongan dan membasahi atap, sementara lidah api mengikuti rumput menuju lumbung. Vina berdiri di batas tanaman keluarganya dengan obor. Danu menyerahkan kendi minyak tanpa menyetujui kehilangan itu, lalu memilih membantu menjaga arah bakar-balik bersama Karsa.'] },
      { chapterNumber: 48, title: 'Kebun Sendiri Dibakar', paragraphs: ['Vina menyalakan baris teh miliknya dari sisi bawah. Karsa dan Danu menjaga api kecil bergerak melawan angin hingga bertemu kebakaran dari puncak. Seluruh pucuk siap petik menjadi batang hitam, tetapi api utama kehilangan bahan sebelum mencapai lumbung. Saat hujan abu reda, Vina tidak memiliki panen untuk dibawa pulang.'] },
      { chapterNumber: 49, title: 'Palu Menempa Cangkul Hangus', paragraphs: ['Karsa membuka bengkel dan mengumpulkan cangkul yang gagangnya terbakar untuk diperbaiki tanpa biaya. Ia mengaku di depan warga bahwa sabit buatannya membantu membuka jalur api, lalu menyerahkan nama pembelinya kepada kepala desa. Vina menyapu abu dari lantai lumbung. Kejujuran Karsa tidak mengembalikan kebunnya, tetapi membuat tanggung jawab tidak lagi ditanggung satu keluarga.'] },
      { chapterNumber: 50, title: 'Tunas Merah di Tanah Hitam', paragraphs: ['Penyelidikan desa menemukan minyak tersimpan di pondok kru Bagas, sementara lumbung tetap berdiri dan rumah lereng selamat. Vina bekerja memetik di kebun tetangga karena lahannya belum menghasilkan. Karsa menancapkan arit pada batas sekat sebagai pengingat pemeriksaan musim depan. Di antara batang teh hitam, tunas merah pertama muncul tanpa menjanjikan panen yang cepat.'] },
    ], justification: 'The ending builds toward a controlled counterfire that costs Vina her own harvest, saves the settlement, and makes Karsa answer openly for the tools he supplied.' },
    { chapters: [
      { chapterNumber: 41, title: 'Anyaman Jembatan Bergeser', paragraphs: ['Danu melihat anyaman pagar jembatan bergeser tiga ruas setelah gerobak kru Bagas melintas malam hari. Sambungan bawah retak, meski mandor memerintahkan warga tetap memakai jalur itu. Vina mengikat serat merah pada tiap silang bambu untuk membaca perubahan beban. Jembatan tersebut menjadi satu-satunya jalan antara rumah mereka dan dusun tempat Danu merawat seorang penanam sakit.'] },
      { chapterNumber: 42, title: 'Keranjang Menguji Bentang', paragraphs: ['Karsa menggantung keranjang batu pada bentang tengah, lalu Vina mencatat silang mana yang turun lebih dahulu. Uji ketiga membuat satu ikatan putus dan batu jatuh ke jurang. Danu meminta jembatan ditutup, tetapi warga seberang belum memiliki persediaan obat. Mereka sepakat membatasi lintasan sambil menyiapkan cara mengirim barang tanpa membawa tubuh melintasi retakan.'] },
      { chapterNumber: 43, title: 'Tali Meluncurkan Obat', paragraphs: ['Danu memasang tali miring dan mengirim bungkusan obat dalam keranjang kecil ke dusun seberang. Percobaan pertama tersangkut di tengah, lalu Vina menambahkan roda kayu buatan Karsa. Bungkusan berikutnya tiba utuh. Jalur sederhana itu belum mengangkut manusia, tetapi memberi mereka kemungkinan memutus jembatan tanpa meninggalkan keluarga sakit sepenuhnya terasing.'] },
      { chapterNumber: 44, title: 'Jejak Lumpur pada Bilah', paragraphs: ['Serat merah bergeser lagi setelah malam tanpa warga melintas. Lumpur pada pagar memuat sekam gudang kantor, menunjukkan gerobak Bagas masih memakai jembatan diam-diam. Vina ingin menangkap rombongan berikutnya, sedangkan Danu menolak menjadikan retakan sebagai perangkap. Mereka memasang lonceng pada pangkal dan mulai memindahkan warga seberang sebelum mencari siapa yang membawa muatan.'] },
      { chapterNumber: 45, title: 'Nenek Terakhir Menyeberang', paragraphs: ['Warga mengantar seorang nenek melewati bentang dengan tali pinggang sebelum hujan turun. Danu tetap di dusun seberang untuk menjaga penanam sakit dan berkata Vina tidak boleh memotong jembatan selagi ia di sana. Vina berjanji menunggu isyarat kain putih dari bukit. Janji itu membatasi tindakannya ketika tiap bunyi bambu menandakan keruntuhan makin dekat.'] },
      { chapterNumber: 46, title: 'Gerobak Datang Saat Hujan', paragraphs: ['Lonceng pangkal berbunyi ketika gerobak kantor membawa peti melaju dalam hujan. Vina dan warga menghadang, tetapi kru memukul kendali dan terus maju. Dua silang bambu patah di belakang roda pertama. Dari seberang, Danu mengangkat kain putih karena pasien telah aman, lalu berteriak agar kakaknya menyelamatkan orang, bukan mempertahankan bentang yang sudah gagal.'] },
      { chapterNumber: 47, title: 'Bentang Tengah Diputus', paragraphs: ['Setelah kru berlari kembali ke sisi kantor, Vina mengayunkan parang pada ikatan utama. Karsa memotong tali kedua dan bentang tengah jatuh bersama gerobak kosong ke dasar jurang. Peti tertahan di sisi atas, tetapi Danu terpisah dari rumah tanpa jalan pulang. Keputusan itu menghentikan lintasan Bagas sekaligus mengubah kehidupan kedua dusun untuk berbulan-bulan.'] },
      { chapterNumber: 48, title: 'Danu Tinggal di Seberang', paragraphs: ['Danu tidur di rumah penanam yang telah pulih dan berbicara dengan Vina melalui jurang saat udara cerah. Ia mengaku marah karena janji pulang mereka hilang bersama jembatan, meski pemotongan tadi menyelamatkan kru. Vina tidak meminta pengampunan cepat. Mereka menyusun giliran keranjang agar makanan, surat, dan obat tetap bergerak sementara bentang baru dirancang.'] },
      { chapterNumber: 49, title: 'Kabel Pertama Direntangkan', paragraphs: ['Karsa merentangkan kabel bekas pengangkut teh di antara dua pangkal, dibantu warga dari kedua sisi. Keranjang besar dapat membawa beras dan alat, tetapi belum aman untuk manusia. Danu mengirim baju kerja Vina yang tertinggal di rumahnya sebagai tanda ia masih menjaga hubungan mereka. Vina membalas dengan bibit cabai dan pesan tanpa janji tanggal kepulangan.'] },
      { chapterNumber: 50, title: 'Dua Ujung dalam Kabut', paragraphs: ['Kecamatan menyita peti kantor yang tertahan dan melarang jembatan dibuka kembali sebelum dibangun ulang. Bagas kehilangan jalur malam, namun dusun tetap terbelah. Vina memutar roda kabel saat keranjang pertama berisi hasil kebun melintas di atas jurang. Dalam kabut, dua ujung jembatan lama bergantung tanpa bertemu, sementara suara Danu terdengar dari sisi lain.'] },
    ], justification: 'The ending turns measured bridge failure into an irreversible demolition that stops Bagas while separating Vina and Danu, then shows a limited material connection rather than instant repair.' },
    { chapters: [
      { chapterNumber: 41, title: 'Lonceng Tanah Bergetar', paragraphs: ['Lonceng tanah di rumah jaga bergetar tanpa angin ketika kendaraan berat kantor melintas di jalan atas. Vina menemukan retak rambut pada dinding sumur warga dan menempelkan empat bilah daun lontar sebagai pengukur. Bu Ningsih mencatat jaraknya. Mereka menduga getaran baru sedang merusak rongga air yang menopang teras bawah.'] },
      { chapterNumber: 42, title: 'Daun Lontar Bergeser', paragraphs: ['Dua bilah lontar bergeser selebar kuku sesudah truk kedua lewat. Vina mengukur retak bersama Mbah Ripto, lalu memindahkan tempayan dari sisi dinding yang melemah. Bagas menyebut perubahan itu akibat kemarau. Vina menolak menutup sumur sebelum keluarga lereng memperoleh tempat mengambil air lain yang dapat dijangkau anak-anak.'] },
      { chapterNumber: 43, title: 'Rongga Bernapas Dingin', paragraphs: ['Karsa menurunkan lampu minyak ke sumur dan nyalanya condong menuju celah batu, menandakan udara bergerak dari rongga bawah jalan. Vina memasukkan serbuk kunyit ke rembesan; warna kuning muncul dekat tiang kantor. Bukti tersebut menghubungkan retakan dengan jalur kendaraan, tetapi menghentikan truk berarti memutus angkutan teh tempat Danu bekerja.'] },
      { chapterNumber: 44, title: 'Jalan Ringan Diuji', paragraphs: ['Warga menguji jalur kebun lama memakai dua keranjang teh dan papan pada bagian berlumpur. Satu papan patah, membuat muatan tumpah, tetapi orang dapat lewat tanpa mendekati sumur. Danu menghitung perjalanan akan bertambah satu jam. Vina meminta percobaan kedua sebelum mengusulkan agar truk dilarang melewati ruas dekat sumur.'] },
      { chapterNumber: 45, title: 'Bagas Menambah Muatan', paragraphs: ['Bagas justru mengirim truk dengan muatan ganda dan menyatakan panen tidak boleh menunggu ketakutan warga. Getarannya menjatuhkan batu dari bibir sumur dan membuat air keruh. Danu kehilangan giliran kerja setelah menolak naik. Ia menyalahkan Vina karena keputusan itu mengancam penghasilan mereka, lalu pergi bermalam di rumah Karsa.'] },
      { chapterNumber: 46, title: 'Tiang Kantor Mulai Miring', paragraphs: ['Hujan singkat melunakkan tanah dan tiang penanda kantor miring ke arah rongga. Bu Ningsih menutup jalan atas memakai bangku sekolah, sementara warga memindahkan air dengan kendi. Vina menyusun catatan getaran, warna kunyit, dan posisi tiang. Bagas mengancam mengambil bangku, tetapi pengemudinya sendiri menolak menyeberangi retakan.'] },
      { chapterNumber: 47, title: 'Jalan Atas Diputus', paragraphs: ['Retakan membelah jalan ketika truk kosong mencoba berbalik. Vina memerintahkan Karsa mencabut dua papan jembatan kecil sehingga kendaraan lain tidak dapat mendekat. Tindakan itu juga menutup rute tercepat menuju pasar. Danu membantu pengemudi turun, namun mengatakan ia belum memaafkan Vina karena memilih keselamatan seluruh lereng tanpa berbicara dengannya.'] },
      { chapterNumber: 48, title: 'Keranjang Menempuh Kebun', paragraphs: ['Panen teh pertama dibawa melalui jalur kebun dengan keranjang kecil bergilir. Perjalanan lambat dan sebagian daun rusak terkena hujan, tetapi tanah dekat sumur berhenti bergerak. Vina menyerahkan upah angkutnya kepada Danu yang kehilangan pekerjaan. Danu menolak uang itu, lalu ikut memperkuat papan jalur tanpa menganggap pertengkaran mereka selesai.'] },
      { chapterNumber: 49, title: 'Air Jernih Kembali', paragraphs: ['Serbuk kunyit tidak lagi muncul di sisi kantor dan air sumur perlahan jernih. Di bibir sumur, Vina mengakui kepada Danu bahwa ia memakai ketakutan kehilangan warga untuk mengabaikan hak kakaknya ikut memutuskan. Danu mengakui penghasilannya membuat ia menutup mata pada retakan. Mereka sepakat bekerja bersama tanpa menjanjikan luka itu segera hilang.'] },
      { chapterNumber: 50, title: 'Jalur Kecil Menjadi Tetap', paragraphs: ['Kecamatan menutup ruas dekat sumur bagi truk dan menetapkan jalur kebun sebagai rute angkut ringan. Bagas kehilangan kecepatan pengiriman, sementara keluarga lereng tetap harus bergiliran membawa teh. Vina dan Danu memasang lonceng tanah di gerobak pertama. Sumur bertahan, tetapi tambahan perjalanan menjadi harga harian yang dibayar seluruh lembah.'] },
    ], justification: 'The ending turns measured vibration into a permanent heavy-vehicle ban, preserves the shared well at a durable transport cost, and resolves the sibling conflict without erasing it.' },
    { chapters: [
      { chapterNumber: 41, title: 'Hujan Es Merobek Atap', paragraphs: ['Hujan es merobek tiga atap bambu dan melukai seorang penanam yang berlari mencari perlindungan. Ramalan radio menyebut badai kedua akan tiba dalam sembilan hari. Bagas mengunci bangunan kantor, sementara lumbung keluarga Vina menjadi satu-satunya ruang dengan balok utuh. Vina membuka pintunya, tetapi lantai sempit tidak mungkin menampung seluruh warga lereng.'] },
      { chapterNumber: 42, title: 'Keranjang Menguji Balok', paragraphs: ['Pada setiap balok, Karsa menggantung bakul berisi batu untuk menguji beban. Satu sambungan berderit sebelum berat setara empat orang tercapai. Mbah Ripto menghitung warga yang sulit berjalan, sedangkan Vina mengukur ruang di antara rak keluarga. Agar lumbung aman, rak penyimpanan harus dibongkar dan kayunya dijadikan penyangga, mengakhiri fungsi yang diwariskan ayahnya.'] },
      { chapterNumber: 43, title: 'Mbah Menolak Tempat Dalam', paragraphs: ['Mbah Ripto menolak tempat dekat pintu karena seorang ibu dengan bayi lebih membutuhkannya. Vina menyusun urutan masuk berdasarkan kemampuan bergerak, bukan kegunaan seseorang saat bekerja. Lelaki tua itu menuduhnya mengasihani usia. Pertengkaran mereka membuat jelas bahwa perlindungan bersama akan gagal bila warga merasa keselamatan harus dibayar dengan menyerahkan martabat.'] },
      { chapterNumber: 44, title: 'Pintu Darurat Dicoba', paragraphs: ['Karsa membuka pintu darurat pada dinding belakang dan warga mencoba keluar tanpa membawa barang. Rak-rak membuat dua jalur menyempit, sementara peti keluarga Vina menghalangi belokan terakhir. Danu meminta peti itu dipindahkan. Vina menolak karena isinya pakaian ibu mereka, lalu menyadari ia sedang mempertahankan kenangan dengan ruang yang mungkin dibutuhkan tubuh hidup.'] },
      { chapterNumber: 45, title: 'Gudang Kantor Tetap Dikunci', paragraphs: ['Para ibu meminta Bagas membuka gudang teh sebagai tempat kedua, tetapi ia menuntut surat pelepasan tuntutan air. Mereka pulang tanpa kesepakatan. Vina menawarkan lumbung lagi, kali ini dengan syarat setiap keluarga hanya membawa satu bungkusan. Mbah Ripto bersedia membantu latihan masuk bila ia boleh memilih sendiri tempat duduk dan tugasnya selama badai.'] },
      { chapterNumber: 46, title: 'Latihan Pertama Gagal', paragraphs: ['Latihan masuk berubah kacau ketika anak-anak mencari orang tua dan warga berebut sudut kering. Mbah Ripto memukul lesung dengan pola berbeda untuk tiap kelompok, membuat arus manusia terpisah tanpa teriakan. Uji ulang selesai lebih cepat, namun rak timur bergoyang saat semua orang duduk. Karsa berkata penyangga tambahan tidak dapat dipasang tanpa menggergaji dudukan permanennya.'] },
      { chapterNumber: 47, title: 'Peti Ibu Dibuka', paragraphs: ['Vina membuka peti ibu bersama Danu dan membagi pakaian di dalamnya kepada keluarga yang atapnya rusak. Mereka menyimpan satu selendang, lalu memakai papan peti untuk memperkuat pintu darurat. Tindakan itu membebaskan ruang, tetapi balok utama masih membutuhkan kayu rak. Di luar, awan es menutup puncak sehari lebih cepat dari ramalan radio.'] },
      { chapterNumber: 48, title: 'Rak Warisan Digergaji', paragraphs: ['Vina menggergaji dudukan rak yang menyatu dengan dinding lumbung. Karsa memasang kayunya sebagai penyangga silang, sementara Mbah Ripto mengatur warga masuk menurut bunyi lesung. Badai menghantam sebelum papan terakhir terpasang. Semua orang berlindung, tetapi karung keluarga Vina yang tak lagi memiliki rak basah ketika air merembes sepanjang lantai.'] },
      { chapterNumber: 49, title: 'Caping pada Bekas Rak', paragraphs: ['Pagi sesudah badai, rumah-rumah masih berdiri meski banyak atap berlubang. Warga menggantung caping pada bekas rak dan membagi bahan makanan yang selamat. Mbah Ripto memilih tetap dekat pintu untuk menyambut keluarga terakhir, bukan karena diperintah Vina. Lumbung tidak dapat kembali menjadi gudang privat, dan hasil panen kini harus disimpan tersebar di beberapa rumah.'] },
      { chapterNumber: 50, title: 'Cahaya Masuk dari Dinding', paragraphs: ['Desa menetapkan lumbung sebagai tempat berlindung tetap dan membangun rak kecil pada rumah-rumah untuk mengganti penyimpanan lama. Bagas belum membuka gudang kantor, sehingga tuntutan terhadapnya berlanjut. Vina menjemur karung basah bersama Danu. Cahaya pagi masuk melalui celah dudukan papan keluarga, menerangi caping berbagai ukuran yang tertinggal setelah warga pulang.'] },
    ], justification: 'The ending forces Vina to dismantle her inherited private storehouse so it can shelter the village, while Mbah Ripto retains agency and storage loss remains unresolved.' },
  ],
  WEAK: [
    { chapters: [
      { chapterNumber: 41, title: 'Kabut Menutup Papan Nama', paragraphs: ['Kabut menutup papan nama di simpang lembah sejak pagi, sementara Vina menunggu jadwal baru dari kantor. Ia membersihkan huruf dengan kain lalu pulang. Tidak ada perubahan pada sengketa air, pilihan keluarga, atau ancaman Bagas. Pekerjaan kecil itu selesai sebelum siang dan tidak dipakai lagi oleh siapa pun.'] },
      { chapterNumber: 42, title: 'Pagar Kebun Dicat', paragraphs: ['Karsa mengecat pagar bengkelnya dengan sisa kapur putih. Vina membantu memegang kaleng dan membicarakan warna yang cepat kering. Mereka tidak menyebut parit, benih, atau tuntutan warga. Setelah pagar selesai, Karsa masuk bengkel dan Vina pulang tanpa informasi atau keputusan yang mengarah pada akhir konflik.'] },
      { chapterNumber: 43, title: 'Keranjang Dicuci Hujan', paragraphs: ['Hujan sore mencuci lumpur dari keranjang panen Danu. Vina menjemurnya di serambi dan mengganti satu ikatan rotan yang longgar. Danu berterima kasih lalu tidur lebih awal. Perawatan tersebut menjaga alat tetap berguna, tetapi hubungan mereka, pekerjaan kebun, dan kuasa kantor tetap persis seperti sebelumnya.'] },
      { chapterNumber: 44, title: 'Kapur Kelas Ditambah', paragraphs: ['Bu Ningsih menerima satu kotak kapur baru dan menyusunnya menurut warna di lemari kelas. Murid-murid memilih kapur biru untuk menggambar gunung. Vina mengantar kotak kosong ke rumah jaga. Tidak ada gambar, percakapan, atau benda dari kegiatan itu yang menyentuh perkara lembah maupun mempersiapkan keputusan akhir.'] },
      { chapterNumber: 45, title: 'Pasar Pindah Sehari', paragraphs: ['Pasar mingguan dipindah ke hari Kamis karena lapangan dipakai pertemuan kecamatan. Vina menyesuaikan daftar belanja dan membeli garam lebih awal. Bagas terlihat di warung tetapi tidak berbicara dengannya. Perubahan jadwal berakhir sebagai urusan rumah tangga tanpa tekanan, bukti, atau hubungan baru.'] },
      { chapterNumber: 46, title: 'Atap Bengkel Ditambal', paragraphs: ['Danu membantu Karsa menambal dua lubang pada atap bengkel menggunakan seng bekas. Vina membawa air minum dan menghitung paku yang tersisa. Hujan tidak lagi masuk setelah pekerjaan selesai. Keberhasilan praktis itu tidak berkaitan dengan konflik utama dan tidak menciptakan pilihan yang perlu dibayar pada penutupan.'] },
      { chapterNumber: 47, title: 'Buku Sekolah Disampul', paragraphs: ['Vina dan Bu Ningsih menyampul buku pelajaran dengan kertas cokelat hingga petang. Mereka menulis nama murid pada sudut kanan dan menumpuk buku menurut kelas. Percakapan hanya menyentuh jadwal ujian. Seluruh pekerjaan selesai rapi, namun tidak satu pun akibat cerita bergerak mendekati jawaban.'] },
      { chapterNumber: 48, title: 'Pemeriksa Tiba Mendadak', paragraphs: ['Rombongan kecamatan tiba dan memeriksa kantor Bagas berdasarkan laporan yang tidak pernah dilihat Vina. Mereka membawa dua peti dokumen ke kota. Warga hanya menonton dari jalan. Vina tidak diminta bersaksi; pekerjaan kecil selama delapan hari itu sama sekali tidak membantu pemeriksaan tersebut.'] },
      { chapterNumber: 49, title: 'Makan Malam Tetap Biasa', paragraphs: ['Vina dan Danu makan ubi rebus sambil membicarakan harga sabun. Mereka mendengar kabar Bagas mungkin dipindahkan, lalu memilih tidur karena harus bangun pagi. Tidak ada ketakutan, harapan, atau luka utama yang mereka sebut. Hubungan kakak-adik berakhir pada kebiasaan yang sama seperti awal.'] },
      { chapterNumber: 50, title: 'Surat Pemindahan Dibaca', paragraphs: ['Kecamatan memindahkan Bagas dan membuka kembali sebagian jatah air melalui surat singkat. Vina membaca pengumuman di gerbang lalu pulang menjemur pakaian. Tidak ada pilihan yang ia buat menghasilkan keputusan itu, dan tidak ada harga atau perubahan diri yang harus dibawa ke musim berikutnya. Cerita berhenti ketika pejabat luar menyelesaikannya.'] },
    ], justification: 'The runway consists of unrelated chores, while an external inspection resolves the conflict without using any prepared action, relationship, or cost.' },
    { chapters: [
      { chapterNumber: 41, title: 'Kebun Bunga Direncanakan', paragraphs: ['Bu Ningsih mengusulkan kebun bunga kecil di samping sekolah agar murid belajar mengenali musim. Vina menggambar empat petak dan memilih bunga berwarna cerah. Mereka menghitung kebutuhan bambu serta pupuk. Rencana tersebut menyenangkan, tetapi tidak berhubungan dengan air, kendali Bagas, atau pertanyaan yang selama ini menekan lembah.'] },
      { chapterNumber: 42, title: 'Bambu Petak Dipotong', paragraphs: ['Karsa memotong bambu menjadi enam belas bilah pendek untuk membatasi petak. Murid-murid mengampelas ujungnya dan menumpuknya di halaman. Vina mencatat jumlah bilah yang selesai. Kegiatan itu maju sesuai rencana kebun, namun tidak menambah bukti, risiko, atau pilihan terhadap konflik utama.'] },
      { chapterNumber: 43, title: 'Benih Bunga Tiba', paragraphs: ['Kiriman benih bunga tiba dari kecamatan dalam lima amplop bergambar. Bu Ningsih membagi setiap amplop kepada kelompok murid. Vina menyimpan satu cadangan di lemari. Tidak ada isi kiriman yang mengubah jatah warga atau membuka hubungan baru; runway terus mengikuti proyek sampingan yang aman.'] },
      { chapterNumber: 44, title: 'Tanah Sekolah Digemburkan', paragraphs: ['Danu membantu menggemburkan tanah sekolah seusai bekerja. Ia dan Vina berbicara tentang jarak tanam serta warna bunga yang disukai ibu mereka. Percakapan terasa hangat tetapi menghindari ketakutan pekerjaan dan sengketa rumah. Kedekatan nostalgia itu tidak menuntut pengakuan atau keputusan sulit.'] },
      { chapterNumber: 45, title: 'Hujan Merusak Dua Petak', paragraphs: ['Hujan merusak dua petak sebelum benih ditanam. Murid memindahkan tanah dan memperkuat batas bambu. Bu Ningsih menganggap pekerjaan ulang itu sebagai latihan kesabaran bagi murid. Kerusakan kecil segera diperbaiki, tidak mempersempit pilihan siapa pun dan tidak menghubungkan proyek bunga pada tekanan yang membentuk cerita.'] },
      { chapterNumber: 46, title: 'Benih Ditanam Bergilir', paragraphs: ['Setiap kelompok menanam satu baris benih lalu memasang papan nama. Vina menyiram memakai air kendi yang dibawa dari rumah. Tidak seorang pun membahas mengapa air sekolah terbatas. Adegan menghasilkan baris tanaman, tetapi menghindari sebab kekurangan dan tidak menyiapkan jawaban akhir.'] },
      { chapterNumber: 47, title: 'Pagar Petak Selesai', paragraphs: ['Pagar kebun bunga selesai dan anak-anak menggantung daun kering sebagai hiasan. Karsa memperbaiki satu sambungan sebelum pulang. Proyek itu kini hampir tuntas tanpa konflik berarti. Vina merasa puas, namun kepuasan tersebut berdiri terpisah dari perjuangan lembah dan tidak membutuhkan pengorbanan.'] },
      { chapterNumber: 48, title: 'Bagas Dicopot Kecamatan', paragraphs: ['Surat dari kecamatan mengumumkan Bagas dicopot setelah audit yang berjalan diam-diam di kota. Warga bersorak di depan sekolah. Vina tidak tahu bukti apa yang dipakai dan tidak pernah diminta memberi keterangan. Konflik utama selesai dari luar sementara kebun bunga menjadi satu-satunya garis tindakan yang mereka bangun.'] },
      { chapterNumber: 49, title: 'Tunas Pertama Terlihat', paragraphs: ['Tunas bunga pertama muncul di petak paling dekat kelas. Bu Ningsih mengajak murid mengukurnya dan Vina menuliskan tinggi pada papan. Danu tersenyum ketika lewat. Momen itu lembut, tetapi tidak menyelesaikan ketakutan, rasa bersalah, atau hubungan yang pernah diuji oleh kuasa Bagas.'] },
      { chapterNumber: 50, title: 'Bunga Mekar di Halaman', paragraphs: ['Semua petak berbunga ketika pejabat baru membuka jatah air penuh. Murid berfoto di halaman dan Vina membagikan benih cadangan. Cerita menutup proyek sekolah secara rapi, namun jawaban terhadap konflik datang dari pejabat yang tidak dipersiapkan dan tidak membebankan akibat pada tokoh utama.'] },
    ], justification: 'A safe flower-garden project occupies the runway while an unseen audit removes the antagonist, leaving the central dramatic question unanswered by the authored actions.' },
    { chapters: [
      { chapterNumber: 41, title: 'Kain Jemur Dikumpulkan', paragraphs: ['Vina mengumpulkan kain jemur sebelum hujan dan melihat satu noda tanah pada ujung selendang. Ia mencucinya sampai pudar lalu menaruh kain di lemari. Kegiatan itu tidak memberikan informasi baru atau menyentuh konflik lembah. Hari berakhir dengan rumah lebih rapi dan keadaan cerita tetap diam.'] },
      { chapterNumber: 42, title: 'Tempayan Dipindah Teduh', paragraphs: ['Danu memindahkan tempayan ke sisi rumah yang teduh agar air tidak cepat hangat. Vina membantu mengganjal dasarnya dengan batu. Mereka membahas letak terbaik lalu selesai. Tidak ada kekurangan air yang diselidiki, tidak ada orang lain dilibatkan, dan hubungan mereka tidak bergerak melampaui kerja rumah.'] },
      { chapterNumber: 43, title: 'Daun Teh Dipilah', paragraphs: ['Vina memilah daun teh yang rusak dari keranjang Danu dan membuangnya ke kompos. Danu menyebut mandor sedang sibuk, tetapi percakapan berhenti di sana. Tidak ada pertanyaan tentang pekerjaan, ancaman, atau pilihan masa depan. Keranjang menjadi bersih tanpa menghasilkan arah bagi cerita.'] },
      { chapterNumber: 44, title: 'Jalan Setapak Disapu', paragraphs: ['Bu Ningsih mengajak murid menyapu jalan menuju sekolah setelah angin membawa daun kering. Vina membantu mengumpulkan tiga tumpukan. Jalan tampak bersih menjelang siang. Perubahan visual itu tidak mengubah risiko, pengetahuan, atau hubungan apa pun dan tidak akan dipakai dalam penutupan.'] },
      { chapterNumber: 45, title: 'Kucing Tidur di Serambi', paragraphs: ['Seekor kucing tidur di serambi rumah jaga sepanjang sore. Vina memberinya sisa nasi dan memperhatikan bulunya mengering. Mbah Ripto tertawa melihatnya. Adegan memberi jeda tenang sesaat, tetapi tidak membawa tekanan, keputusan, atau tanda baru yang berhubungan dengan pertanyaan akhir lembah.'] },
      { chapterNumber: 46, title: 'Panci Ditambal Karsa', paragraphs: ['Karsa menambal lubang panci Vina dengan keping logam. Ia menguji hasilnya memakai segelas air dan tidak menemukan tetesan. Vina membayar dengan dua ikat sayur. Pertukaran selesai tanpa membuka perkara lain; keberhasilan kecil ini tidak mempersiapkan kemenangan, kehilangan, atau perubahan tokoh.'] },
      { chapterNumber: 47, title: 'Kabut Turun Lebih Awal', paragraphs: ['Kabut turun sebelum senja dan membuat warga menutup jendela. Vina menyalakan lampu lalu menunggu Danu pulang. Ketika kakaknya tiba, mereka minum teh tanpa membahas kantor. Cuaca hanya mengubah suasana, bukan pilihan mereka, sehingga runway tetap tidak membangun hubungan menuju akhir.'] },
      { chapterNumber: 48, title: 'Kabar Audit dari Kota', paragraphs: ['Pedagang membawa kabar bahwa kantor Bagas sedang diaudit di kota. Vina mendengarnya di pasar dan pulang tanpa mencari sumber. Tidak ada hasil pekerjaan bab sebelumnya yang memicu audit atau dapat diserahkan sebagai bukti. Perubahan besar memasuki cerita sebagai kabar dari tempat lain.'] },
      { chapterNumber: 49, title: 'Lampu Dapur Dipadamkan', paragraphs: ['Vina dan Danu makan dalam diam lalu memadamkan lampu dapur. Mereka mengetahui audit mungkin selesai besok, tetapi tidak membicarakan harapan atau ketakutan. Luka keluarga tidak diberi nama dan tidak ada tindakan yang masih harus dipilih. Malam berlalu seperti malam biasa.'] },
      { chapterNumber: 50, title: 'Bagas Pergi dengan Truk', paragraphs: ['Bagas pergi menggunakan truk kantor setelah surat pencopotan tiba. Warga melihat dari pinggir jalan dan kembali bekerja. Vina menyapu serambi lalu memberi makan kucing. Konflik selesai tanpa keterlibatannya, sementara seluruh runway rumah tangga tidak memperoleh makna baru atau akibat yang bertahan.'] },
    ], justification: 'Domestic observations repeat without causal accumulation, and the antagonist exits through an external audit that none of the runway material prepares.' },
    { chapters: [
      { chapterNumber: 41, title: 'Toples Garam Diberi Label', paragraphs: ['Vina memberi label pada tiga toples dapur agar Danu tidak salah mengambil garam dan gula. Ia menulis huruf besar lalu menaruh semuanya di rak. Perbaikan tersebut langsung selesai dan tidak menyentuh sengketa air, pekerjaan, atau kuasa kantor. Tidak ada akibat yang perlu dibawa menuju akhir.'] },
      { chapterNumber: 42, title: 'Rak Bumbu Dibersihkan', paragraphs: ['Rak bumbu dibersihkan dari jelaga dan botol kosong dibuang. Danu membantu memindahkan piring selama Vina menyeka papan. Mereka tidak membahas konflik desa apa pun. Dapur menjadi lebih terang, tetapi perubahan itu tidak membuka informasi, menguji hubungan, atau mempersempit pilihan tokoh.'] },
      { chapterNumber: 43, title: 'Kayu Bakar Ditumpuk', paragraphs: ['Karsa mengirim kayu bakar dan Vina menumpuknya menurut ukuran di samping tungku. Pekerjaan berlangsung sampai sore tanpa gangguan. Setiap batang memperoleh tempat, namun cerita tidak memperoleh arah. Persediaan rumah itu juga tidak digunakan untuk tindakan penting pada bab-bab berikutnya.'] },
      { chapterNumber: 44, title: 'Sendok Kayu Diganti', paragraphs: ['Sendok kayu lama retak dan Danu membeli pengganti di pasar. Vina mencobanya saat memasak bubur lalu menyimpan yang lama sebagai kayu bakar. Masalah kecil itu mendapat penyelesaian lengkap, tetapi sama sekali tidak berkaitan dengan pertanyaan dramatis yang seharusnya dijawab pada penutupan.'] },
      { chapterNumber: 45, title: 'Tirai Dapur Dicuci', paragraphs: ['Tirai dapur dicuci di sungai dan dijemur pada pagar. Bu Ningsih membantu memerasnya sambil membahas menu sekolah. Mereka tidak menyentuh perkara Bagas atau kebutuhan warga. Kebersamaan singkat itu aman dan ramah, tanpa pengungkapan, risiko, maupun kewajiban baru bagi siapa pun.'] },
      { chapterNumber: 46, title: 'Beras Dipindah Karung', paragraphs: ['Vina memindahkan beras ke karung kering setelah wadah lama lembap. Ia menghitung takaran dan menutup ikatan dengan rapi. Danu mengangkat karung ke sudut. Tindakan praktis tersebut tidak menghasilkan bukti, tekanan baru, atau perubahan yang akan menentukan akhir cerita utama mereka.'] },
      { chapterNumber: 47, title: 'Piring Pecah Diganti', paragraphs: ['Satu piring jatuh ketika kucing melompat ke meja. Vina menyapu pecahan dan membeli piring baru dari tetangga. Insiden selesai sebelum malam. Tidak ada simbol, petunjuk, atau akibat hubungan yang muncul; runway terus berisi gangguan rumah kecil harian yang saling terpisah.'] },
      { chapterNumber: 48, title: 'Surat Kecamatan Tiba', paragraphs: ['Kurir membawa surat bahwa Bagas dicopot berdasarkan penyelidikan rahasia. Vina membacanya dua kali karena tidak pernah mengetahui penyelidikan tersebut berlangsung. Semua pekerjaan dapur pada hari-hari sebelumnya tidak berkontribusi pada keputusan. Jawaban utama datang tanpa persiapan dan tanpa pilihan tokoh.'] },
      { chapterNumber: 49, title: 'Bubur Dimasak Seperti Biasa', paragraphs: ['Vina memakai sendok baru untuk memasak bubur, sementara Danu menata tiga toples berlabel. Mereka membicarakan keberangkatan Bagas seperti berita cuaca biasa kemarin. Tidak ada penyelesaian emosional atau keputusan masa depan. Benda-benda runway hanya kembali menjalankan fungsi rumah tangga biasa.'] },
      { chapterNumber: 50, title: 'Dapur Tetap pada Tempatnya', paragraphs: ['Pejabat baru membuka gerbang air dan warga menerima jatah tanpa syarat. Vina pulang, menutup tirai bersih, lalu meletakkan piring baru di rak. Cerita berhenti pada dapur yang lebih rapi, sementara pusat konflik diselesaikan sepenuhnya oleh orang luar dan tidak meninggalkan harga.'] },
    ], justification: 'A sequence of self-contained kitchen chores prepares no dramatic answer; external officials resolve the conflict without using any runway setup.' },
    { chapters: [
      { chapterNumber: 41, title: 'Papan Cuaca Dicat Biru', paragraphs: ['Bu Ningsih mengecat papan cuaca sekolah dengan warna biru dan meminta Vina menuliskan tanggal. Cat mengering menjelang siang. Mereka belum menentukan data apa yang akan dicatat. Papan itu menjadi benda baru, tetapi tidak memiliki hubungan jelas dengan sengketa air atau keputusan akhir.'] },
      { chapterNumber: 42, title: 'Satu Awan Digambar', paragraphs: ['Seorang murid menggambar awan pada papan cuaca setelah gerimis singkat. Vina menambahkan satu garis untuk arah angin. Catatan pertama memberi kegiatan bagi kelas, namun belum membentuk pola atau menjelaskan tekanan yang dihadapi lembah. Tidak ada orang dewasa lain yang melihat hasilnya.'] },
      { chapterNumber: 43, title: 'Angin Berubah Sore', paragraphs: ['Menjelang petang, arah angin berbalik sehingga Vina menggambar garis kedua. Bu Ningsih mengatakan mereka perlu sebulan sebelum menyimpulkan apa pun. Papan mulai memuat perbedaan kecil antarhari, tetapi data itu sama sekali tidak memandu tindakan dan tidak terkait dengan keputusan Bagas.'] },
      { chapterNumber: 44, title: 'Hujan Tidak Dicatat', paragraphs: ['Hujan malam turun ketika sekolah tutup sehingga tidak seorang pun memberi tanda pada papan. Keesokan pagi Vina menebak lamanya berdasarkan genangan. Ia menulis tanda tanya. Kekosongan selama satu malam tersebut memperlihatkan keterbatasan catatan, tetapi belum menciptakan akibat bagi konflik utama.'] },
      { chapterNumber: 45, title: 'Murid Membuat Simbol', paragraphs: ['Murid-murid menyepakati simbol matahari, kabut, dan gerimis. Mereka berlatih menggambarnya berulang kali di beberapa lembar kertas. Vina merasa papan kelak berguna untuk kebun, tetapi belum menyebut cara. Persiapan memperoleh bahasa kecil tanpa sasaran dramatis atau risiko yang benar-benar nyata.'] },
      { chapterNumber: 46, title: 'Papan Dipindah Teras', paragraphs: ['Angin merobohkan papan sehingga Karsa memindahkannya ke teras kelas. Dua tanda lama yang dibuat pada awal pekan tergores saat papan itu diangkat. Vina menyalin yang masih terbaca. Tindakan menyelamatkan catatan, namun tidak menambah kaitan pada sengketa dan tidak mempersempit pilihan akhir.'] },
      { chapterNumber: 47, title: 'Kabut Dicatat Bersama', paragraphs: ['Tiga murid mencatat kabut pagi dari halaman sekolah dan membandingkan tebalnya dengan dua hari sebelumnya. Bu Ningsih menyimpan kapur sesudah kelas. Kebiasaan kecil perlahan mulai terbentuk, tetapi tidak ada pola cukup panjang, saksi dewasa, atau keputusan yang bergantung pada hasilnya.'] },
      { chapterNumber: 48, title: 'Audit Kantor Diumumkan', paragraphs: ['Kecamatan mengumumkan audit kantor Bagas setelah menerima laporan rahasia dari kota. Vina menyadari catatan cuaca buatannya sama sekali tidak membantu pemeriksa kantor. Ia tetap menulis satu simbol matahari baru pada papan. Konflik bergerak mendadak melalui jalur yang tidak pernah disiapkan runway.'] },
      { chapterNumber: 49, title: 'Tanda Matahari Memudar', paragraphs: ['Hujan menghapus sebagian simbol matahari dan Vina menebalkannya. Danu bertanya apakah papan akan dipakai musim depan. Vina menjawab mungkin sambil menaruh kapur di kotak kayu dekat pintu kelas. Percakapan memberi kemungkinan tipis bagi kebiasaan baru, tetapi tidak menyentuh perasaan atau pilihan yang menutup cerita.'] },
      { chapterNumber: 50, title: 'Papan Cuaca Disimpan', paragraphs: ['Setelah Bagas dicopot dan jatah dibuka oleh pejabat baru, sekolah menyimpan papan cuaca untuk masa libur panjang. Vina membawa kapur pulang. Proyek memperoleh masa depan sederhana, namun tidak menjawab bagaimana tokoh menghadapi kuasa, dan kemenangan tetap berasal dari audit eksternal.'] },
    ], justification: 'A modest weather-recording practice gains continuity but never connects to the central conflict, whose external resolution remains unearned.' },
  ],
  BORDERLINE: [
    { chapters: [
      { chapterNumber: 41, title: 'Tiga Rumah Menyimpan Air', paragraphs: ['Vina mencatat tiga rumah yang masih memiliki tempayan penuh dan menggambar letaknya pada sepotong kulit jagung. Ia belum menanyakan apakah air boleh dibagi. Catatan itu memberi gambaran awal tentang cadangan warga, tetapi tidak mencakup keluarga lereng atas atau kebutuhan harian mereka.'] },
      { chapterNumber: 42, title: 'Satu Tempayan Dipinjamkan', paragraphs: ['Bu Ningsih melihat kulit jagung itu dan menawarkan setengah tempayannya kepada keluarga terdekat. Vina membantu membawa dua kendi. Satu rumah memperoleh air, sementara daftar kebutuhan masih kosong dan gerbang tetap dikuasai Bagas. Tindakan tersebut berguna tetapi belum menjadi jawaban bersama.'] },
      { chapterNumber: 43, title: 'Kulit Jagung Hampir Robek', paragraphs: ['Hujan semalaman membuat kulit jagung lembap dan satu nama warga di ujung catatan memudar. Vina menyalin dua titik ke kertas sekolah, namun titik ketiga hilang. Ia menyadari catatannya perlu diperluas. Kehilangan kecil itu memperlambat upaya tanpa menghapus kemungkinan membangun jaringan cadangan.'] },
      { chapterNumber: 44, title: 'Dua Ibu Menambah Titik', paragraphs: ['Dua ibu menambahkan rumah mereka pada kertas dan menyebut jumlah kendi yang dapat dipinjamkan. Vina belum menghitung anak atau orang tua yang membutuhkan lebih banyak. Peta mulai menjadi milik kelompok kecil, tetapi pembagiannya masih berdasarkan kedekatan, bukan kebutuhan yang terukur.'] },
      { chapterNumber: 45, title: 'Bagas Melarang Pengangkutan', paragraphs: ['Bagas melarang warga membawa air melintasi jalan kantor dengan alasan tumpahan membuat jalur licin. Vina memindahkan satu pengiriman kecil melalui kebun kopi milik tetangga. Larangan memberi tekanan nyata, namun kelompok belum menyepakati apakah mereka akan menentangnya atau terus memakai jalan memutar.'] },
      { chapterNumber: 46, title: 'Kendi Pecah di Kebun', paragraphs: ['Satu kendi pecah di jalur kebun dan air untuk keluarga lereng habis sebelum tiba. Vina menandai lokasi itu serta meminta Karsa membuat pikulan lebih stabil. Kegagalan tersebut menghasilkan perbaikan praktis, tetapi jaringan masih kecil dan tidak mampu mengganti jatah gerbang.'] },
      { chapterNumber: 47, title: 'Pikulan Pertama Dicoba', paragraphs: ['Karsa menyelesaikan pikulan dua sisi dan Vina mengantar air tanpa tumpah. Tiga keluarga menerima bagian air pada hari itu tanpa menunggu gerbang. Bu Ningsih meminta daftar kebutuhan sebelum giliran berikutnya. Mereka memperoleh cara terbatas yang dapat bertahan, meski kuasa Bagas belum berubah.'] },
      { chapterNumber: 48, title: 'Audit Tidak Memakai Peta', paragraphs: ['Pemeriksa kecamatan datang membawa perkara lain dan tidak meminta peta tempayan Vina. Mereka langsung menyegel kantor Bagas berdasarkan berkas lama yang dibawa dari kota. Upaya warga tetap membantu tiga keluarga, tetapi tidak berperan dalam keputusan besar yang mulai menutup konflik.'] },
      { chapterNumber: 49, title: 'Daftar Kebutuhan Belum Lengkap', paragraphs: ['Vina dan Bu Ningsih mencatat lima keluarga, lalu berhenti karena dua rumah tidak dapat ditemui. Danu menawarkan membantu setelah kerja. Jaringan cadangan memiliki alat dan sekutu, tetapi cakupannya belum cukup untuk musim kering berikutnya atau untuk menggantikan tata air resmi.'] },
      { chapterNumber: 50, title: 'Gerbang Dibuka Pejabat Baru', paragraphs: ['Pejabat baru membuka gerbang setelah Bagas dicopot melalui audit kota. Vina menyimpan peta tempayan dan pikulan untuk keadaan darurat. Upaya kecil mereka memperoleh kegunaan masa depan, namun jawaban utama tidak lahir darinya dan ketahanan seluruh lereng masih belum benar-benar terbukti.'] },
    ], justification: 'A small household-water network creates partial utility and future runway, but remains incomplete and does not earn the externally delivered resolution.' },
    { chapters: [
      { chapterNumber: 41, title: 'Bayang Renggang pada Daun', paragraphs: ['Vina melihat bayang pagar membentuk celah lebar pada daun talas dan menandai ujungnya dengan arang. Ia menduga tiang bergeser, tetapi belum mengukur tanah atau memanggil saksi. Tanda tersebut memberi satu titik pembanding yang dapat diperiksa lagi, tanpa menjelaskan sebab maupun bahayanya.'] },
      { chapterNumber: 42, title: 'Garis Arang Berpindah', paragraphs: ['Keesokan pagi bayang jatuh dua jari dari garis arang. Mbah Ripto melihat perbedaan itu dan menyarankan memasang tali ukur. Mereka belum melakukannya karena harus memperbaiki atap. Pengamatan kini memiliki saksi, namun belum cukup membedakan gerak tanah dari perubahan arah matahari.'] },
      { chapterNumber: 43, title: 'Tali Diikat Satu Tiang', paragraphs: ['Vina mengikat tali dari satu tiang ke batu tetap dan memberi simpul pada panjang awal. Ia tidak memasang pembanding pada tiang lain. Persiapan sederhana itu dapat menunjukkan perubahan lokal, tetapi tidak memetakan lereng atau menentukan rumah mana yang perlu dikosongkan.'] },
      { chapterNumber: 44, title: 'Simpul Menegang Sedikit', paragraphs: ['Sesudah truk berat lewat, tali terasa lebih tegang dan simpul bergeser sedikit sekali. Bu Ningsih membantu mencatat waktunya. Bagas menolak menghentikan kendaraan karena satu tali dianggap tidak cukup. Bukti memberi tekanan awal, tetapi keputusan keselamatan belum dapat dibuat dengan yakin.'] },
      { chapterNumber: 45, title: 'Truk Lewat Sekali Lagi', paragraphs: ['Truk kedua melintas dan tali menegang sampai seratnya berbunyi. Vina segera memindahkan dua tempayan dari dekat tiang, namun keluarga lain tetap tinggal di rumah. Ia belum memiliki jalur pengganti atau dukungan pengemudi. Tindakan mengurangi satu risiko tanpa mengubah kebijakan jalan.'] },
      { chapterNumber: 46, title: 'Tali Putus Saat Hujan', paragraphs: ['Hujan deras semalaman membuat tali putus sebelum ukuran berikutnya sempat dicatat. Vina menyimpan kedua ujung basah sebagai bukti, tetapi panjangnya sudah berubah. Pemeriksa desa mengatakan catatan mereka patut diperhatikan namun belum cukup menetapkan larangan kendaraan berat di jalan desa itu.'] },
      { chapterNumber: 47, title: 'Dua Tiang Baru Dipasang', paragraphs: ['Karsa memasang dua tiang pembanding baru jauh dari jalan. Vina memulai catatan baru dan mengajak murid melihat dari jarak aman. Sistem yang lebih baik lahir terlambat, setelah bukti awal rusak. Mereka belum tahu apakah hasilnya akan datang sebelum retakan membesar.'] },
      { chapterNumber: 48, title: 'Pengemudi Memilih Jalan Kebun', paragraphs: ['Satu pengemudi melihat tiang miring dari kejauhan dan memilih jalan kebun atas kemauan sendiri. Bagas kemudian memotong upah harian pengemudi tersebut. Pilihan itu memperlihatkan alternatif mungkin dipakai, tetapi belum ada aturan bersama atau jaminan pengemudi lain akan mengikuti rute tersebut.'] },
      { chapterNumber: 49, title: 'Catatan Baru Baru Dua Hari', paragraphs: ['Dua hari pengukuran menunjukkan gerak kecil pada satu tiang baru. Vina meminta penundaan truk, dan kantor memberi waktu tiga hari untuk bukti tambahan. Mereka memperoleh ruang singkat, bukan keputusan tetap, sementara hubungan Vina dan Danu tentang risiko pekerjaan belum dibahas.'] },
      { chapterNumber: 50, title: 'Jalan Ditutup Sementara', paragraphs: ['Kecamatan menutup jalan berat selama dua pekan sambil menunggu pengukuran lengkap. Truk beralih sementara ke kebun, dan sumur belum rusak. Vina menyimpan tali putus serta catatan baru. Akhir memberi perlindungan terbatas dan kemungkinan lanjut, tetapi biaya, aturan tetap, dan konflik keluarga belum terselesaikan.'] },
    ], justification: 'Incremental shadow and rope measurements earn a temporary closure, yet incomplete evidence and unresolved family costs keep the ending only partially satisfying.' },
    { chapters: [
      { chapterNumber: 41, title: 'Bau Besi dari Mata Air', paragraphs: ['Vina mencium bau besi pada mata air kecil di kebun kopi dan mengisi satu botol bening. Ia belum tahu apakah perubahan berasal dari pipa kantor atau tanah setelah hujan. Sampel tersebut memberi benda yang dapat dibandingkan, tetapi belum memiliki lokasi sumber atau saksi lain.'] },
      { chapterNumber: 42, title: 'Endapan Jingga Terbentuk', paragraphs: ['Semalam kemudian endapan jingga tipis muncul di dasar botol bening tersebut. Karsa melihatnya dan menyarankan mengambil sampel dari dua titik lain. Mereka hanya memiliki satu botol kosong. Temuan itu memperkuat kecurigaan, namun belum membedakan pencemaran baru dari mineral alami lembah.'] },
      { chapterNumber: 43, title: 'Botol Kedua dari Hulu', paragraphs: ['Bu Ningsih meminjamkan botol kaca lain dan Vina mengambil air dari hulu. Sampel baru itu tetap jernih. Perbedaan tersebut menunjukkan perubahan terjadi di antara dua titik, tetapi wilayahnya masih mencakup kebun luas dan tidak ada jalur spesifik yang dapat diperiksa.'] },
      { chapterNumber: 44, title: 'Pakis Menutup Pipa', paragraphs: ['Vina menemukan pakis tertekan di lereng antara dua sumber. Ia mengangkat satu daun dan melihat ujung benda hijau, lalu berhenti agar lokasi tidak rusak. Bagas melarang orang masuk. Petunjuk fisik kini ada, tetapi belum dilihat saksi resmi atau diuji hubungannya dengan air.'] },
      { chapterNumber: 45, title: 'Lokasi Difoto dengan Arang', paragraphs: ['Bu Ningsih menggambar posisi pakis, batu, dan kedua mata air pada papan kayu kecil. Mereka tidak dapat mendekati benda hijau karena kru berjaga. Gambar menjaga orientasi dan membuat temuan dapat dibagikan, namun belum membuktikan fungsi benda atau siapa yang memasangnya.'] },
      { chapterNumber: 46, title: 'Hujan Menggeser Pakis', paragraphs: ['Hujan deras menggeser pakis basah dan memperlihatkan pipa pendek yang berakhir di tanah lembap. Vina memanggil dua ibu, tetapi aliran sudah berhenti. Mereka melihat bentuknya tanpa dapat mengambil cairan. Bukti bertambah, sementara hubungan antara pipa dan endapan masih tidak langsung.'] },
      { chapterNumber: 47, title: 'Pipa Dibawa Kecamatan', paragraphs: ['Dua petugas kecamatan mencabut ruas pipa hijau untuk diperiksa di kantor. Bagas menyatakan itu saluran pupuk lama terbengkalai. Vina menyerahkan dua botol, gambar, dan nama saksi. Pemeriksa menerima semuanya tetapi mengatakan hasil uji baru datang setelah sidang penempatan mandor selesai.'] },
      { chapterNumber: 48, title: 'Gerbang Dibuka Sementara', paragraphs: ['Kantor membuka jatah air tambahan sementara agar warga berhenti memakai mata air kebun. Perubahan mendadak itu membantu beberapa keluarga, namun juga membuat sampel baru sulit diperoleh kembali. Vina memilih menyimpan botol lama, sadar buktinya mungkin tidak cukup untuk keputusan final.'] },
      { chapterNumber: 49, title: 'Hasil Uji Belum Datang', paragraphs: ['Malam sebelum sidang, hasil uji pipa belum juga tiba. Vina mengakui kepada Bu Ningsih bahwa ia ingin satu temuan menyelesaikan seluruh perkara. Guru itu mengingatkan bahwa penyelidikan dapat benar meski belum lengkap. Mereka membawa semua berkas tanpa menjanjikan kemenangan pasti.'] },
      { chapterNumber: 50, title: 'Mandor Dipindah Sementara', paragraphs: ['Kecamatan memindahkan Bagas sementara berdasarkan pelanggaran akses, bukan pencemaran yang belum terbukti. Mata air ditutup sampai hasil uji keluar dan warga menerima jatah tambahan. Vina memperoleh perlindungan terbatas, tetapi sumber endapan, tanggung jawab akhir, dan masa depan pipa tetap terbuka.'] },
    ], justification: 'A bounded contamination investigation earns temporary protection and removal, but delayed testing leaves causation and durable resolution incomplete.' },
  ],
}
